     fwrite ($fd, '@sha '     . $sha1 . "\n");
     fwrite ($fd, '@direct '  . $direct . "\n");
     fwrite ($fd, '@echo '    . $echo . "\n");
     fwrite ($fd, '@workspace '. $ws . "\n");
