}

function Rerror ($cmd, $msg, $input) {
   $txt = '<pre>ERROR: &lt;' . $cmd . '...&gt; ' . $msg . ' <em>in</ 
em></pre><p>';
   $txt = $txt . '<pre>' . $input . '</pre>';
