function Rlog ($msg) {
   $fn = r_dir . DIRECTORY_SEPARATOR . 'R.log';
   $fd = fopen ($fn, 'a');
   fwrite ($fd, date('r') . ' ' . $msg . "\n");
   fclose($fd);
