function makeStyle ($param, $default) {
   $list = explode (';', $default);
   $n    = count($list);
   $arr  = array();
   for ($i=0; $i<$n; $i++) {
     $pair = explode (':', $list[$i]);
     $arr[$pair[0]] = $pair[1];
   }
   $list = explode (';', $param);
   $n    = count($list);
   for ($i=0; $i<$n; $i++) {
     $pair = explode (':', $list[$i]);
     $arr[$pair[0]] = $pair[1];
   }
   $list = array_keys($arr);
   $ret  = '';
   for ($i=0; $i<$n; $i++) {
     if (strlen($list[$i])>0) {
       $ret = $ret . $list[$i] . ':' . $arr[$list[$i]] . ';';
     }
   }
   return $ret;
}

function makeHTML ($input, $direct) {
   if (!direct) {
     $ret = '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01  
Transitional//EN" "http://www.w3.org/TR/html4/loose.dtd">';
     $ret = $ret . '<html><head><meta http-equiv="expires"  
content="0"></head><body>';
     $ret = $ret . $input;
//  $ret = $ret . '<hr>' . date("d.m.Y") . ' ' . date("H:i:s");
     $ret = $ret . '</body></html>';
   } else {
     $ret = $input;
   }
   return $ret;
}

function renderRform( $input , $params ) {
   array_key_exists('name', $params) or error ('Rform', 'attribute  
"name" required', $input);
   $name = $params['name'];
   $ret  = '<form action="' . extractUrl(r_cgi) . '" method="post"  
target="' . $name . '">';
   $ret  = $ret . '<input type="hidden" name="R" value="' . $name .  
'">';
   $ret  = $ret . $input;
   $ret  = $ret . '</form>';
   return $ret;
}

function runRinShell ($cmd, $chmf, &$r_exitcode) {
   $stdout = "";
   if (security>1) {
     $msg = shell_exec (sudo . $cmd);
     if ($chmf!='') {
       $cmd = sudo . chmod . $chmf;
       exec ($cmd, $stdout, $r_exitcode);
#      error ('R', $cmd, $msg);
     }
   } else {
     exec ($cmd, $stdout, $r_exitcode);
   }

   foreach($stdout as $row) $msg .= $row . "\n";

#  error ('R', $cmd, $msg);
   return ($msg);
}

function runShell ($cmd) {
   $cmd = str_replace ("\n", ' ', $cmd);
   return (shell_exec ($cmd));
}

